        self.nombre = nombre
        self.hambre = 50
        self.energia = 50
        self.felicidad = 50
        self.salud = 100
        self.tiempo_transcurrido = 0

    def comer(self):
        if self.hambre < 100:
            self.hambre += 10
            self.energia += 5
            self.felicidad += 3
        else:
            print("El Tamagotchi ya no tiene hambre.")
        self.validar_estado()

    def dormir(self):
        if self.energia < 100 and self.salud > 0:
            self.energia += 15
            self.felicidad += 2
        else:
            print("El Tamagotchi no necesita dormir o su salud es muy baja.")
        self.validar_estado()

    def jugar(self):
        if self.energia > 0 and self.felicidad < 100:
            self.felicidad += 10
            self.hambre += 5
            self.energia -= 3
        else:
            print("El Tamagotchi no tiene energía suficiente o su felicidad ya está al máximo.")
        self.validar_estado()

    def estado(self):
        print(f"Estado de {self.nombre}:")
        print(f"Hambre: {self.hambre}%")
        print(f"Energía: {self.energia}%")
        print(f"Felicidad: {self.felicidad}%")
        print(f"Salud: {self.salud}%")

    def pasar_tiempo(self):
        self.tiempo_transcurrido += 1
        if self.hambre > 0:
            self.hambre -= 1
        if self.energia > 0:
            self.energia -= 2
        if self.felicidad > 0:
            self.felicidad -= 1
        if self.salud < 100:
            self.salud += 1
        self.validar_estado()

    def validar_estado(self):
        for atributo, valor in zip(['hambre', 'energia', 'felicidad', 'salud'], [self.hambre, self.energia, self.felicidad, self.salud]):
            if valor < 0:
                setattr(self, atributo, 0)
            elif valor > 100:
                setattr(self, atributo, 100)

