            self.energia += 20
            self.energy_modifiers()
            print(f"{self.nombre} se ha quedado dormido y su energía es ahora {self.energia}.")

    def jugar(self):
        if self.felicidad >= 90:
            print("El Tamagotchi no necesita jugar.")
        else:
            self.felicidad += 20
            self.happiness_modifiers()
