        self.hambre = max(0, self.hambre - 5)
        self.energia = max(0, self.energia - 5)
        self.felicidad = max(0, self.felicidad - 5)

    def verificar_estado(self):
        if self.salud == 0:
            print(f"{self.nombre} ha muerto...")
            return True
        elif self.hambre <= 0 or self.energia <= 0 or self.felicidad <= 0:
            print(f"{self.nombre} se siente muy mal y necesita atención.")
            return True
        else:
            return False

    def hunger_modifiers(self):
        if self.hunger >= 90:
            self.salud -= 5
            print(f"Hummm, {self.nombre} no está en el mejor de los estados. Su salud disminuye.")

    def energy_modifiers(self):
        if self.energy >= 90:
            self.felicidad -= 5
            print(f"{self.nombre} necesita un poco de ejercicio más. Su felicidad disminuye.")

    def happiness_modifiers(self):
        if self.happiness >= 90:
            self.salud += 5
            print(f"Jugar es una buena idea, {self.nombre}. Su salud aumenta.")

